document.write("<!-- MotionSwap.html — 🔄 MotionSwap (🎬 Motion chat, mo-26): §67 C boss FORM SWAPS — S = Motion.swap(kind, {from, to}) paint-agnostic: the boss file hands its old + new art, Motion plays the 1.5 s safe cutscene (tell → cover → onSwap 750 → reveal + ⚪ → settle → onDone 1500): 🌙 wipe · 🐦‍⬛ ringLift · ☀️ fanSnap · ⚡ swell · 🖤 bud · 🟥 swirl · 🦁 pageFlip · 🔆 lampTurn · 🔥 climb. LAZY: Motion.need('swap', cb) online (Code.gs INCLUDE_LAZY_ AvatarKit) · eager with CreatureKit · inline offline + in the harness. Adds only Motion.swap + Motion.SWAP. No server tags. BUILT by Test Harness/motion/build_motion.py from motion/src/MotionSwap.js — never edit by hand. Rules: FX Bible F1–F16 · Motion rules.md §79–82. -->\n<script>\n/* ================= 🔄 MotionSwap (mo-26, 🎬 Motion chat, 2026-11-27) — §67 C boss FORM SWAPS: every island transformation in ONE paint-agnostic call =================\n   Ask: Motion rules §67 C · plan §79 · look test §80 (Aowu \"go\" 18:50 + \"ok\" 18:55). Sources: Island 2 build pack §44o · Island 3 build pack 2 §45p · Island 5 build pack 2 §49o · Avateer guard rail ① (a phase change = a 1.5 s safe cutscene).\n   S = Motion.swap(kind, {from, to, x, y (the feet on your canvas), k, dir, t0, ms (default 1500), calm, day, seed, hour ('noon' | 'dusk' | 'night', pageFlip), lamp ([x, y] local, lampTurn), bits ([paint …] the hats, swirl), cols (kind colours), onSwap, onDone})\n     from / to = paint(g, s) — YOUR boss drawn standing, feet at 0, 0 (up = −y), s = {t, u, phase} · Motion measures both once (box · head point) · each body goes through ONE offscreen layer (tints + ⚪ silhouette).\n     each frame S.draw(g, t) = back FX · old / new body · front FX (the game stops drawing the boss until onDone) · S.at(t) → {u, phase: tell | cover | reveal | settle | done, swapped, done, shake}\n     S.on(name, fn) — sound / game moments (✨ UISound): 'swap' (750) · 'done' (1500) + per kind (Motion.SWAP.EVENTS) · fired ONCE each as t passes them.\n   Beats: ① tell 0–350 (wind-up ≥ 300) · ② cover 350–700 · ③ onSwap 750 (switch form · HP · music) · ④ reveal 750–1150 (⚪ the NEW form's own silhouette once, F2 — not wipe · swell · swirl; calm none) · ⑤ settle → onDone 1500.\n   Kinds: 🌙 wipe · 🐦‍⬛ ringLift · ☀️ fanSnap · ⚡ swell · 🖤 bud · 🟥 swirl · 🦁 pageFlip · 🔆 lampTurn · 🔥 climb.\n   Born split + LAZY: Motion.need('swap', cb) on AvatarKit pages (Code.gs INCLUDE_LAZY_) · eager with CreatureKit (bosses swap) · inline offline + in the harness.\n   Pure on t (seeded) · plain canvas + one cached glow sprite per colour · no area flash (F12) · never destination-out · FX ≤ 0.3 ms a frame (the boss's own paint not counted). */\n(function reg() {\nconst M = window.Motion;\nif (!M) { if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', reg, {once: true}); return; }\nif (M.SWAP) return;\nconst cl = (v, a, b) => v < a ? a : v > b ? b : v, seg = (t, a, b) => cl((t - a) / (b - a), 0, 1), lerp = (a, b, u) => a + (b - a) * u;\nconst E = {cubicOut: u => 1 - Math.pow(1 - u, 3), cubicIn: u => u * u * u, sine: u => 0.5 - 0.5 * Math.cos(Math.PI * u), backOut: u => {const s = 1.9; u -= 1; return u * u * ((s + 1) * u + s) + 1;}, quadOut: u => 1 - (1 - u) * (1 - u)};\nconst T = {tell: 0.35, cover: 0.7, swap: 0.75, reveal: 1.15, end: 1.5};\nfunction rng(seed){ let s = (seed | 0) * 9301 + 49297; return () => (s = (s * 16807) % 2147483647) / 2147483647; }\nconst GLOW = {};\nfunction glow(col){ if(GLOW[col]) return GLOW[col]; const c = document.createElement('canvas'); c.width = c.height = 64; const q = c.getContext('2d'), gr = q.createRadialGradient(32, 32, 0, 32, 32, 32);\n  gr.addColorStop(0, col); gr.addColorStop(1, 'rgba(0,0,0,0)'); q.fillStyle = gr; q.fillRect(0, 0, 64, 64); return GLOW[col] = c; }\nfunction dot(g, S, x, y, r, col, a){ g.save(); g.globalAlpha = (a == null ? 1 : a) * (S.day ? 0.55 : 1); g.globalCompositeOperation = S.day ? 'source-over' : 'lighter'; g.drawImage(glow(col), x - r, y - r, r * 2, r * 2); g.restore(); }\nfunction mk(w, h){ const c = document.createElement('canvas'); c.width = Math.max(1, w | 0); c.height = Math.max(1, h | 0); return c; }\n// 📏 measure a paint once (alpha scan) → box in local units\nfunction measure(paint, z){ z = z || 1; const R = 2 / z, X0 = -220 * z, Y0 = -330 * z, W = 440 * z, H = 380 * z, c = mk(W * R, H * R), q = c.getContext('2d');\n  q.setTransform(R, 0, 0, R, -X0 * R, -Y0 * R); try{ paint(q, {t: 0, u: 0, phase: 'measure'}); }catch(e){}\n  const d = q.getImageData(0, 0, c.width, c.height).data; let x0 = 1e9, x1 = -1e9, y0 = 1e9, y1 = -1e9, hx = 0;\n  for(let y = 0; y < c.height; y += 2) for(let x = 0; x < c.width; x += 2){ if(d[(y * c.width + x) * 4 + 3] > 24){ if(x < x0) x0 = x; if(x > x1) x1 = x; if(y < y0){ y0 = y; hx = x; } if(y > y1) y1 = y; } }\n  if(x1 < x0) return {x0: -35, x1: 35, y0: -100, y1: 0, hx: 0};\n  if(z < 8 && (x0 <= 2 || y0 <= 2 || x1 >= c.width - 3 || y1 >= c.height - 3)) return measure(paint, z * 2);   // a big boss → measure again on a 2 × wider sheet\n  return {x0: x0 / R + X0, x1: x1 / R + X0, y0: y0 / R + Y0, y1: y1 / R + Y0, hx: hx / R + X0}; }\n\nfunction swap(kind, o){\n  o = o || {}; const K = KINDS[kind] ? kind : 'wipe';\n  const S = {kind: K, o, x: o.x || 0, y: o.y || 0, k: o.k || 1, dir: o.dir || 1, t0: o.t0 || 0, sc: (o.ms || 1500) / 1500, calm: !!o.calm, day: !!o.day, seed: o.seed == null ? 7 : o.seed,\n    from: o.from || ((g) => {}), to: o.to || ((g) => {}), fired: {}, hooks: {}, oc: {}};\n  const a = measure(S.from), b = measure(S.to);\n  S.A = a; S.B = b; const pad = 10;\n  S.bx = Math.min(a.x0, b.x0) - pad; S.by = Math.min(a.y0, b.y0) - pad - 30; S.bw = Math.max(a.x1, b.x1) + pad - S.bx; S.bh = Math.max(a.y1, b.y1, 0) + pad + 40 - S.by;\n  S.H = Math.max(-a.y0, -b.y0); S.W = Math.max(a.x1 - a.x0, b.x1 - b.x0); S.cx = (Math.min(a.x0, b.x0) + Math.max(a.x1, b.x1)) / 2;\n  S.at = t => { const u = (t - S.t0) / S.sc; const phase = u < T.tell ? 'tell' : u < T.cover ? 'cover' : u < T.swap ? 'cover' : u < T.reveal ? 'reveal' : u < T.end ? 'settle' : 'done';\n    return {u, phase, swapped: u >= T.swap, done: u >= T.end, shake: KINDS[K].shake ? KINDS[K].shake(S, u) : 0}; };\n  // 🎨 one body through an offscreen layer: {clip(g), tint: [[y0, y1, col, a] …] (source-atop bands), white, sx, sy, dy, dx, px, alpha, flipX}\n  S.body = (g, which, u, f) => { f = f || {}; const paint = which === 'to' ? S.to : S.from, tr = g.getTransform ? g.getTransform() : {a: 1, b: 0};\n    const R = cl(Math.hypot(tr.a, tr.b) * 1, 1, 3); const c = S.oc[which] || (S.oc[which] = mk(S.bw * R, S.bh * R));\n    if(c.width !== Math.ceil(S.bw * R)){ c.width = Math.ceil(S.bw * R); c.height = Math.ceil(S.bh * R); }\n    const q = c.getContext('2d'); q.setTransform(1, 0, 0, 1, 0, 0); q.globalCompositeOperation = 'source-over'; q.globalAlpha = 1; q.clearRect(0, 0, c.width, c.height);\n    q.setTransform(R, 0, 0, R, -S.bx * R, -S.by * R); paint(q, {t: S.t0 + u * S.sc, u, phase: which});\n    if(f.tint || f.white){ q.globalCompositeOperation = 'source-atop';\n      if(f.white){ q.globalAlpha = f.white; q.fillStyle = '#FFFFFF'; q.fillRect(S.bx, S.by, S.bw, S.bh); }\n      (f.tint || []).forEach(([y0, y1, col, al]) => { q.globalAlpha = al; q.fillStyle = col; q.fillRect(S.bx, y0, S.bw, y1 - y0); }); }\n    g.save(); if(f.clip) f.clip(g); if(f.alpha != null) g.globalAlpha *= f.alpha;\n    const px = f.px == null ? S.cx : f.px; g.translate(px + (f.dx || 0), f.dy || 0); g.scale(f.sx || 1, f.sy || 1); g.translate(-px, 0);\n    g.drawImage(c, S.bx, S.by, S.bw, S.bh); g.restore(); };\n  S.on = (n, fn) => { (S.hooks[n] = S.hooks[n] || []).push(fn); return S; };\n  const fire = (n, u) => { S.fired[n] = 1; (S.hooks[n] || []).forEach(fn => { try { fn({name: n, u, kind: K}); } catch (e) {} }); };\n  S.draw = (g, t) => { const st = S.at(t), u = st.u;\n    g.save(); g.translate(S.x + (st.shake ? Math.sin(u * 90) * st.shake : 0), S.y); g.scale(S.k * S.dir, S.k);\n    if(u < 0) S.body(g, 'from', 0); else if(u >= T.end) S.body(g, 'to', u); else KINDS[K].draw(g, S, u);\n    g.restore();\n    if(u >= 0){ (EVENTS[K] || []).forEach(([n, at]) => { if(u >= at && !S.fired[n]) fire(n, u); });\n      if(u >= T.swap && !S.fired.swap){ fire('swap', u); if(o.onSwap) o.onSwap(S); }\n      if(u >= T.end && !S.fired.done){ fire('done', u); if(o.onDone) o.onDone(S); } }\n    return st; };\n  return S;\n}\n// ⚪ the new form's own white silhouette pop (F2, 1 frame ≈ 40 ms; calm none)\nfunction pop(g, S, u, at, f){ if(S.calm || u < at || u > at + 0.045) return false; S.body(g, 'to', u, Object.assign({white: 1}, f || {})); return true; }\nfunction sparkle(g, S, x, y, r, col, a){ dot(g, S, x, y, r * 2.2, col, a * 0.6); g.save(); g.globalAlpha = a; g.fillStyle = S.day ? '#3a2a10' : '#FFFFFF'; g.beginPath();\n  g.moveTo(x, y - r); g.lineTo(x + r * 0.25, y - r * 0.25); g.lineTo(x + r, y); g.lineTo(x + r * 0.25, y + r * 0.25); g.lineTo(x, y + r); g.lineTo(x - r * 0.25, y + r * 0.25); g.lineTo(x - r, y); g.lineTo(x - r * 0.25, y - r * 0.25); g.fill(); g.restore(); }\nfunction rimStroke(g, S, w){ if(S.day){ g.save(); g.lineWidth = w + 2.2; g.strokeStyle = 'rgba(30,20,50,0.55)'; g.stroke(); g.restore(); } }\n\nconst KINDS = {\n// 🌙 wipe — Light-Line Sweep (Tsukimi, I2): the moon's light / dark line sweeps across him; behind it = the new size, clothes + pose\n//   the moon glyph above WAXES with the line (crescent → half → full) · a silver rim light rides just behind the line · the dark side ahead is a touch dimmer · no ⚪ (soft)\nwipe: {draw(g, S, u){\n  const H = S.H, x0 = S.cx - S.W * 0.72, x1 = S.cx + S.W * 0.72, top = Math.min(S.A.y0, S.B.y0) - 6, p = lerp(x0, x1, E.sine(seg(u, T.tell, T.reveal))), bul = S.W * 0.2, day = S.day;\n  const X = y => p + bul * (1 - Math.pow((y - top / 2) / (-top / 2), 2));\n  const path = (g2, ahead, off) => { off = off || 0; g2.beginPath(); g2.moveTo(ahead ? x1 + 400 : x0 - 400, top - 60); for(let i = 0; i <= 18; i++){ const y = lerp(top - 60, 40, i / 18); g2.lineTo(X(y) + off, y); } g2.lineTo(ahead ? x1 + 400 : x0 - 400, 40); g2.closePath(); };\n  const strip = (g2, w) => { g2.beginPath(); for(let i = 0; i <= 18; i++){ const y = lerp(top - 60, 40, i / 18); g2.lineTo(X(y), y); } for(let i = 18; i >= 0; i--){ const y = lerp(top - 60, 40, i / 18); g2.lineTo(X(y) - w, y); } g2.closePath(); };\n  const moving = u > T.tell && u < T.reveal, ph = seg(u, T.tell, T.reveal);\n  // 🌙 the moon glyph: appears in the tell, waxes with the line, breaks into 3 motes at the end (F5)\n  const cA = E.cubicOut(seg(u, 0.04, 0.26)) * (1 - seg(u, 1.28, 1.42)), cy = top - 20, mr = 9;\n  if(cA > 0){ dot(g, S, S.cx, cy, 26, 'rgba(190,200,255,0.75)', cA * (0.5 + ph * 0.4));\n    g.save(); g.globalAlpha = cA; g.translate(S.cx, cy); g.scale(cA * 0.3 + 0.7, cA * 0.3 + 0.7);\n    g.beginPath(); g.arc(0, 0, mr, 0, Math.PI * 2); g.fillStyle = day ? '#4B4A86' : '#2E3270'; g.fill(); if(day){ g.lineWidth = 1.6; g.strokeStyle = 'rgba(20,20,60,0.6)'; g.stroke(); }\n    const w = Math.cos(Math.PI * (1 - ph * 0.85)) * mr; g.beginPath(); g.arc(0, 0, mr, -Math.PI / 2, Math.PI / 2, true); g.ellipse(0, 0, Math.abs(w), mr, 0, Math.PI / 2, -Math.PI / 2, w > 0); g.fillStyle = day ? '#B7B8F2' : '#EEF0FF'; g.fill();\n    g.beginPath(); g.arc(-mr * 0.35, -mr * 0.2, mr * 0.18, 0, Math.PI * 2); g.arc(-mr * 0.1, mr * 0.4, mr * 0.12, 0, Math.PI * 2); g.fillStyle = day ? 'rgba(80,80,150,0.35)' : 'rgba(150,160,230,0.45)'; g.fill(); g.restore(); }\n  if(u > 1.28){ const v = seg(u, 1.28, T.end); for(let i = 0; i < 3; i++) sparkle(g, S, S.cx + (i - 1) * (6 + v * 10), cy - v * 16 + Math.abs(i - 1) * 4, 3 * (1 - v), '#E9ECFF', 1 - v); }\n  // tell: silver motes gather to the line's start\n  if(u < T.tell + 0.05){ const r = rng(S.seed); for(let i = 0; i < (S.calm ? 5 : 10); i++){ const v = seg(u, 0.02 * i, 0.22 + 0.02 * i), sx = x0 - 20 - r() * 34, sy = top * (0.1 + r() * 0.9); sparkle(g, S, lerp(sx, X(sy), E.cubicOut(v)), sy, 2.2, '#D6DCFF', v * (1 - seg(u, T.tell, T.tell + 0.05))); } }\n  // bodies: the old form ahead of the line (a touch dimmer near it) · the new form behind it (silver rim light right behind the line)\n  S.body(g, 'from', u, {clip: g2 => { path(g2, true); g2.clip(); }, tint: null});\n  if(moving){ g.save(); path(g, true); g.clip(); strip(g, -14); g.clip(); S.body(g, 'from', u, {tint: [[S.by, S.by + S.bh, day ? '#2A2A60' : '#0E1030', 0.35]]}); g.restore(); }\n  if(u > T.tell){ S.body(g, 'to', u, {clip: g2 => { path(g2, false); g2.clip(); }});\n    if(moving){ g.save(); path(g, false); g.clip(); strip(g, 10); g.clip(); S.body(g, 'to', u, {tint: [[S.by, S.by + S.bh, day ? '#9EA8FF' : '#E6ECFF', 0.55]]}); g.restore(); } }\n  // the line: a cel band (soft glow · silver · white core) + moon dust trailing behind it\n  if(moving){ const a = seg(u, T.tell, T.tell + 0.06) * (1 - seg(u, T.reveal - 0.06, T.reveal));\n    for(let i = 0; i <= 9; i++){ const y = lerp(top, 0, i / 9); dot(g, S, X(y), y, 12, 'rgba(160,175,255,0.85)', 0.5 * a); }\n    g.save(); g.globalAlpha = a; g.beginPath(); for(let i = 0; i <= 18; i++){ const y = lerp(top, 0, i / 18); i ? g.lineTo(X(y), y) : g.moveTo(X(y), y); } g.lineCap = 'round';\n    if(day){ g.lineWidth = 5; g.strokeStyle = 'rgba(30,30,90,0.5)'; g.stroke(); } g.lineWidth = 3.4; g.strokeStyle = day ? '#8C93F0' : '#B9C2FF'; g.stroke(); g.lineWidth = 1.3; g.strokeStyle = '#FFFFFF'; g.stroke(); g.restore();\n    const r = rng(S.seed + 3); for(let i = 0; i < (S.calm ? 7 : 14); i++){ const y = top * (0.05 + r() * 0.95), lag = (u * 3 + r()) % 1, d = 4 + lag * 30; sparkle(g, S, X(y) - d, y - lag * 6, (1.4 + r() * 1.8) * (1 - lag), '#D6DCFF', (1 - lag) * a); } }\n}},\n// 🐦‍⬛ ringLift — Wind Rise (Kuro, I2): a gust lifts his feathers into a ring that climbs the body (the ring IS the edge: below it = the new outfit), lifts him, drops him in · feathers fall\nringLift: {draw(g, S, u){\n  const H = S.H, W = S.W, cx = S.cx, N = S.calm ? 10 : 14, rx = W * 0.66, ry = rx * 0.26, day = S.day, top = Math.min(S.A.y0, S.B.y0);\n  const C = Object.assign({vane: day ? '#2F3480' : '#4C54C0', vaneD: day ? '#1E2260' : '#343A96', tip: '#F4EAD2', quill: '#FFFFFF', wind: day ? '#5A6AB8' : '#E8F2FF'}, S.o.cols || {});\n  const climb = E.sine(seg(u, T.tell, 1.08)), yr = lerp(2, top - 8, climb), fly = seg(u, 1.08, 1.4);\n  const lift = u < 1.08 ? -12 * E.cubicOut(seg(u, T.tell, 0.62)) : -12 * (1 - E.cubicIn(seg(u, 1.08, 1.2))), land = seg(u, 1.2, 1.36), sq = land > 0 && land < 1 ? Math.sin(Math.PI * land) * 0.09 : 0;\n  const feather = (fx, fy, a, s, back, al) => { g.save(); g.translate(fx, fy); g.rotate(a); g.scale(s, s); g.globalAlpha = al;\n    g.beginPath(); g.moveTo(0, -12); g.bezierCurveTo(5.5, -6, 5, 5, 0.5, 11); g.bezierCurveTo(-3, 5, -4.5, -5, 0, -12); g.fillStyle = back ? C.vaneD : C.vane; g.fill(); if(day){ g.lineWidth = 1.2; g.strokeStyle = 'rgba(10,10,40,0.6)'; g.stroke(); }\n    g.beginPath(); g.moveTo(0, -12); g.bezierCurveTo(3.4, -9.5, 3.6, -6.5, 2.2, -4.5); g.lineTo(-1.6, -5.5); g.bezierCurveTo(-2.4, -8, -1.6, -10.5, 0, -12); g.fillStyle = C.tip; g.fill();\n    g.beginPath(); g.moveTo(0.2, -10); g.quadraticCurveTo(1.2, 0, 0.5, 13); g.lineWidth = 0.9; g.strokeStyle = C.quill; g.stroke(); g.restore(); };\n  const gather = E.cubicOut(seg(u, 0.06, T.tell));\n  const ring = back => { if(u < 0.06 || fly >= 1) return; const spread = 1 + E.cubicOut(fly) * 1.2;\n    for(let i = 0; i < N; i++){ const an = i / N * Math.PI * 2 + u * 7.5, s = Math.sin(an); if(back !== (s < 0)) continue;\n      const g0 = seg(gather, i / N * 0.5, 0.5 + i / N * 0.5), fx = cx + Math.cos(an) * rx * spread * lerp(1.5, 1, g0), fy = lerp(4, yr + lift + s * ry * spread, g0) - fly * 26;\n      feather(fx, fy, an + Math.PI / 2 + Math.sin(u * 9 + i) * 0.3, (0.95 + (i % 3) * 0.12) * (back ? 0.92 : 1), back, g0 * (1 - fly) * (back ? 0.9 : 1)); } };\n  // wind: curls at the feet (tell) → 2 white streak arcs that spin with the ring\n  const wind = back => { const a = (u < T.tell ? seg(u, 0.02, 0.2) : 1) * (1 - seg(u, 1.05, 1.2)); if(a <= 0) return; g.save(); g.lineCap = 'round';\n    for(let i = 0; i < 3; i++){ const a0 = u * 10 + i * 2.1, y = u < T.tell ? -2 - i * 4 : yr + lift + (i - 1) * 7, r0 = rx * (u < T.tell ? 0.55 + i * 0.22 : 1.05 + i * 0.08); const mid = a0 + 0.8, inBack = Math.sin(mid) < 0; if(back !== inBack) continue;\n      g.beginPath(); g.ellipse(cx, y, r0, r0 * 0.26, 0, a0, a0 + 1.6); if(day){ g.lineWidth = 3.2; g.strokeStyle = 'rgba(20,20,60,0.4)'; g.stroke(); } g.lineWidth = 2 - i * 0.4; g.strokeStyle = C.wind; g.globalAlpha = a * 0.85; g.stroke(); } g.restore(); };\n  wind(true); ring(true);\n  const clipAbove = g2 => { g2.beginPath(); g2.rect(S.bx - 80, S.by - 80, S.bw + 160, yr + lift + 80 - S.by); g2.clip(); }, clipBelow = g2 => { g2.beginPath(); g2.rect(S.bx - 80, yr + lift, S.bw + 160, 400); g2.clip(); };\n  const f = {dy: lift, sx: 1 + sq, sy: 1 - sq};\n  if(u < 1.08){ S.body(g, 'from', u, Object.assign({clip: clipAbove}, f)); if(u > T.tell) S.body(g, 'to', u, Object.assign({clip: clipBelow}, f)); }\n  else { S.body(g, 'to', u, f); pop(g, S, u, 1.2, f); }\n  ring(false); wind(false);\n  // the drop: a soft dust ring + 6 little puffs\n  if(land > 0 && land < 1){ g.save(); g.globalAlpha = 1 - land; g.strokeStyle = day ? '#6A5A8A' : '#DDE6FF'; g.lineWidth = 2; g.beginPath(); g.ellipse(cx, 0, W * (0.35 + land * 0.55), W * (0.35 + land * 0.55) * 0.24, 0, 0, Math.PI * 2); g.stroke(); g.restore();\n    for(let i = 0; i < 6; i++){ const an = (i / 6) * Math.PI * 2, d = W * (0.3 + land * 0.5); g.beginPath(); g.arc(cx + Math.cos(an) * d, Math.sin(an) * d * 0.24 - land * 4, 3.4 * (1 - land) + 0.5, 0, Math.PI * 2); g.fillStyle = day ? 'rgba(120,110,150,0.6)' : 'rgba(220,225,255,0.55)'; g.fill(); } }\n  // loose feathers drift down, swinging like leaves (F5: fewer, smaller, gone)\n  if(fly > 0){ const r = rng(S.seed + 9), n = S.calm ? 4 : 8; for(let i = 0; i < n; i++){ const w = seg(u, 1.08 + i * 0.015, T.end), sw = Math.sin(w * 7 + i * 1.7);\n      feather(cx + (r() - 0.5) * W * 1.7 + sw * 9, top - 30 * r() + E.quadOut(w) * H * (0.55 + r() * 0.4), sw * 0.9 + 1.4, 0.8 * (1 - w * 0.4), false, 1 - w); } }\n}},\n// ☀️ fanSnap — Fan Snap (Hinata, I2): the fan opens behind her (she peeks) → snaps SHUT round her in 2 frames (hold-then-snap) → spins 1.5 turns, edge-on at the swap → TAK! springs open on the new form + ⚪ + sun rays → folds away into sparkles\nfanSnap: {draw(g, S, u){\n  const H = S.H, W = S.W, cx = S.cx, L = H * 0.98, day = S.day, n = 12;\n  const C = Object.assign({a: day ? '#E0362A' : '#FF5A44', b: day ? '#F2A81E' : '#FFC93C', rib: day ? '#6A2A10' : '#8A3A18', rim: '#FFF4C8', hub: day ? '#7A4A20' : '#9A5A2A', sun: '#FFE58A'}, S.o.cols || {});\n  const fan = (spread, alpha, rot) => { if(spread <= 0.02 || alpha <= 0) return; g.save(); g.globalAlpha = alpha; g.translate(cx, 6); g.rotate(rot || 0);\n    const a0 = -Math.PI / 2 - spread / 2, step = spread / n;\n    for(let i = 0; i < n; i++){ const s0 = a0 + step * i, s1 = s0 + step, mid = (s0 + s1) / 2; // pleat = 2 cel halves (lit + shade)\n      g.beginPath(); g.moveTo(0, 0); g.arc(0, 0, L, s0, mid); g.closePath(); g.fillStyle = i % 2 ? C.b : C.a; g.fill();\n      g.beginPath(); g.moveTo(0, 0); g.arc(0, 0, L, mid, s1); g.closePath(); g.fillStyle = i % 2 ? C.b : C.a; g.fill(); g.globalAlpha = alpha * 0.22; g.fillStyle = '#5A1A00'; g.fill(); g.globalAlpha = alpha; }\n    // ribs + the rim band + white edge\n    g.strokeStyle = C.rib; g.lineWidth = 1; for(let i = 0; i <= n; i++){ const s = a0 + step * i; g.beginPath(); g.moveTo(Math.cos(s) * L * 0.3, Math.sin(s) * L * 0.3); g.lineTo(Math.cos(s) * L * 0.97, Math.sin(s) * L * 0.97); g.stroke(); }\n    g.beginPath(); g.arc(0, 0, L * 0.9, a0, a0 + spread); g.lineWidth = L * 0.06; g.strokeStyle = C.sun; g.stroke(); g.beginPath(); g.arc(0, 0, L, a0, a0 + spread); g.lineWidth = 2; g.strokeStyle = C.rim; g.stroke();\n    if(day){ g.beginPath(); g.moveTo(0, 0); g.arc(0, 0, L + 1, a0, a0 + spread); g.closePath(); g.lineWidth = 1.4; g.strokeStyle = 'rgba(60,20,10,0.55)'; g.stroke(); }\n    g.beginPath(); g.arc(0, 0, L * 0.3, a0, a0 + spread); g.lineTo(0, 0); g.closePath(); g.fillStyle = C.hub; g.fill(); g.beginPath(); g.arc(0, 0, L * 0.07, 0, Math.PI * 2); g.fillStyle = C.sun; g.fill(); g.restore(); };\n  // the shut fan = a pleated pod round her; sx = its turn (|cos|), the pleats slide as it spins\n  const closed = (sx, th, sq) => { g.save(); g.translate(cx, 0); g.scale(Math.max(0.04, sx) * (1 + sq), 1 - sq); const hw = W * 0.6, tp = -H - 18;\n    const pod = () => { g.beginPath(); g.moveTo(0, tp); g.bezierCurveTo(hw, tp + H * 0.3, hw * 1.02, -H * 0.12, hw * 0.5, 8); g.lineTo(-hw * 0.5, 8); g.bezierCurveTo(-hw * 1.02, -H * 0.12, -hw, tp + H * 0.3, 0, tp); g.closePath(); };\n    pod(); g.fillStyle = C.a; g.fill(); g.save(); pod(); g.clip(); const off = ((th / Math.PI) % 1) * hw * 0.5;\n    for(let i = -6; i <= 6; i++){ const x = i * hw * 0.25 + off; g.fillStyle = i % 2 ? C.b : C.a; g.fillRect(x - hw * 0.125, tp, hw * 0.25, H + 30); g.globalAlpha = 0.2; g.fillStyle = '#5A1A00'; g.fillRect(x, tp, hw * 0.125, H + 30); g.globalAlpha = 1; }\n    g.fillStyle = C.sun; g.fillRect(-hw * 1.1, -H * 0.15, hw * 2.2, H * 0.06); g.restore();\n    pod(); g.lineWidth = 2 / Math.max(0.3, sx); g.strokeStyle = day ? 'rgba(60,20,10,0.75)' : C.rim; g.stroke(); g.restore();\n    if(sx < 0.2){ g.save(); g.globalAlpha = 1 - sx / 0.2; g.strokeStyle = '#FFFFFF'; g.lineWidth = 2; g.beginPath(); g.moveTo(cx, -H - 14); g.lineTo(cx, 6); g.stroke(); g.restore(); } };\n  if(u < 0.38){ fan(E.backOut(seg(u, 0.03, 0.3)) * 2.5, 1); S.body(g, 'from', u, {dy: -3 * Math.sin(Math.PI * seg(u, 0.1, 0.38))}); }\n  else if(u < 0.86){ const th = E.sine(seg(u, 0.43, T.swap)) * Math.PI * 3, sx = u < 0.43 ? (u < 0.405 ? 1.45 : 1) : Math.abs(Math.cos(th)), sq = u > T.swap ? Math.sin(Math.PI * seg(u, T.swap, 0.86)) * 0.14 : 0;\n    closed(sx, th, sq);\n    if(u < 0.45){ const a = 1 - seg(u, 0.38, 0.45); g.save(); g.globalAlpha = a; g.strokeStyle = day ? '#6A2A10' : '#FFF4C8'; g.lineWidth = 2.2; g.lineCap = 'round'; for(let i = 0; i < 6; i++){ const an = -Math.PI / 2 + (i - 2.5) * 0.55, r0 = H * 0.75, r1 = H * 0.95; g.beginPath(); g.moveTo(cx + Math.cos(an) * r0 * 0.7, -H * 0.5 + Math.sin(an) * r0); g.lineTo(cx + Math.cos(an) * r1 * 0.7, -H * 0.5 + Math.sin(an) * r1); g.stroke(); } g.restore(); } }\n  else { const v = seg(u, 0.86, 1.02), fold = E.cubicIn(seg(u, 1.18, 1.42)), spread = (v < 1 ? E.backOut(v) : 1) * 2.6 * (1 - fold), fade = 1 - seg(u, 1.36, 1.44);\n    fan(spread, fade, fold * 1.1); const st = Math.sin(Math.PI * v) * 0.06; S.body(g, 'to', u, {sx: 1 - st * 0.5, sy: 1 + st}); pop(g, S, u, 0.86, {sx: 1 - st * 0.5, sy: 1 + st});\n    if(u < 1.06){ const a = 1 - seg(u, 0.86, 1.06); dot(g, S, cx, -H * 0.55, H * 0.6, 'rgba(255,214,110,0.7)', a * 0.55); g.save(); g.globalAlpha = a; g.lineCap = 'round';\n      for(let i = 0; i < 9; i++){ const an = -Math.PI / 2 + (i - 4) * 0.33, r0 = L * (1.02 + seg(u, 0.86, 1.06) * 0.22), r1 = r0 + 7 + (i % 2) * 6; g.beginPath(); g.moveTo(cx + Math.cos(an) * r0, 6 + Math.sin(an) * r0); g.lineTo(cx + Math.cos(an) * r1, 6 + Math.sin(an) * r1);\n        if(day){ g.lineWidth = 4; g.strokeStyle = 'rgba(80,40,0,0.45)'; g.stroke(); } g.lineWidth = 2.6; g.strokeStyle = day ? '#E09A00' : '#FFF1A0'; g.stroke(); } g.restore(); }\n    if(fold > 0){ const r = rng(S.seed + 2), w = seg(u, 1.3, T.end); for(let i = 0; i < (S.calm ? 4 : 8); i++){ const an = -Math.PI / 2 + (r() - 0.5) * 2.4 + fold * 1.1, d = L * (0.4 + r() * 0.6); sparkle(g, S, cx + Math.cos(an) * d, 6 + Math.sin(an) * d - w * 12, 2.8 * (1 - w), C.sun, (1 - w) * seg(u, 1.22, 1.3)); } } }\n}},\n// ⚡ swell — Cloud Swell (Gorogoro, I2): squash-and-stretch on the body (puff → spread → TOWER), a boiling cel cloud bank wraps him + hides the swap, the new form comes out as an ANVIL (wide, flat top) and settles · NEVER a pop · a drum ring on *don*\nswell: {draw(g, S, u){\n  const H = S.H, W = S.W, cx = S.cx, day = S.day;\n  const C = Object.assign({dark: day ? '#7C86A6' : '#7A84A8', mid: day ? '#B4BCD2' : '#C6CEE6', light: day ? '#EEF1F8' : '#F6F8FF', zap: '#FFF27A', drum: day ? '#B08800' : '#FFE14A'}, S.o.cols || {});\n  let sx = 1, sy = 1;\n  if(u < 0.5){ const v = E.sine(seg(u, 0.1, 0.5)); sx = 1 + v * 0.16; sy = 1 - v * 0.08; }\n  else if(u < 0.72){ const v = E.sine(seg(u, 0.5, 0.72)); sx = lerp(1.16, 0.86, v); sy = lerp(0.92, 1.26, v); }\n  else if(u < 0.8){ sx = 0.86; sy = 1.26; }\n  else { const v = seg(u, 0.8, 1.0), w = seg(u, 1.0, 1.32); sx = u < 1.0 ? lerp(0.86, 1.2, E.cubicOut(v)) : lerp(1.2, 1, E.backOut(w)); sy = u < 1.0 ? lerp(1.26, 0.84, E.cubicOut(v)) : lerp(0.84, 1, E.backOut(w)); }\n  // the cloud bank: seeded lumps in the body's ellipse (scaled with the body) · boil (radius wobbles, never a sine twice) · cel = dark under · mid · light top-left\n  const bank = E.cubicOut(seg(u, 0.42, 0.66)) * (1 - E.cubicIn(seg(u, 0.84, 1.08))), r = rng(S.seed + 4), lumps = [];\n  for(let i = 0; i < 20; i++){ const a = r() * Math.PI * 2, d = Math.sqrt(r()) * 0.95; lumps.push([Math.cos(a) * d, Math.sin(a) * d, 0.26 + r() * 0.16, r() * 6, i]); }\n  lumps.sort((p, q) => p[1] - q[1]);\n  const anvil = u > 0.8 ? E.cubicOut(seg(u, 0.8, 0.98)) : 0, ex = W * 0.52, ey = H * 0.55;\n  const lumpXY = l => [cx + l[0] * ex * sx * (1 + anvil * (l[1] < -0.3 ? 0.6 : 0.1)), -ey * sy + l[1] * ey * sy * (1 - anvil * (l[1] < -0.3 ? 0.35 : 0)) - (anvil * (l[1] < -0.3 ? 0 : 0))];\n  const cloud = (k, col, dx, dy, rs) => { g.fillStyle = col; g.beginPath(); lumps.forEach(l => { const [x, y] = lumpXY(l), rr = l[2] * W * bank * (0.86 + 0.14 * Math.sin(u * 11 + l[3])) * rs; if(rr > 0.5){ g.moveTo(x + dx + rr, y + dy); g.arc(x + dx, y + dy, rr, 0, Math.PI * 2); } }); g.fill(); };\n  // the body under the bank: from → to cross-fade only while it is fully covered (0.7 → 0.78)\n  const cov = u > 0.66 && u < 0.84;\n  if(u < 0.7) S.body(g, 'from', u, {sx, sy}); else if(u < 0.78){ const v = seg(u, 0.7, 0.78); S.body(g, 'from', u, {sx, sy, alpha: 1 - v}); S.body(g, 'to', u, {sx, sy, alpha: v}); } else S.body(g, 'to', u, {sx, sy});\n  if(bank > 0.02){ g.save(); g.globalAlpha = Math.min(1, bank * 1.6) * (cov ? 1 : 0.95);\n    if(day){ cloud(1, 'rgba(40,45,70,0.5)', 0, 2.2, 1.06); } cloud(1, C.dark, 0, 3, 1); cloud(1, C.mid, 0, 0, 0.94); cloud(1, C.light, -2.5, -3.5, 0.55); g.restore();\n    // ⚡ 2 tiny zaps inside the bank (≤ 3 a second, F12), the only bright thing\n    [0.55, 0.68].forEach((at, i) => { if(u > at && u < at + 0.045 && !S.calm){ const x = cx + (i ? 9 : -11), y = -H * 0.62 * sy; g.save(); g.strokeStyle = C.zap; g.lineWidth = 2; g.lineJoin = 'round'; g.beginPath(); g.moveTo(x - 2, y - 9); g.lineTo(x + 3, y - 2); g.lineTo(x - 2, y + 1); g.lineTo(x + 3, y + 9); if(day){ g.lineWidth = 3.4; g.strokeStyle = 'rgba(80,60,0,0.6)'; g.stroke(); g.lineWidth = 2; g.strokeStyle = C.zap; } g.stroke(); g.restore(); dot(g, S, x, y, 16, 'rgba(255,240,120,0.8)', 0.6); } }); }\n  // break-up (F5): small lumps drift out from the anvil and shrink · rain-free\n  if(u > 0.86 && u < 1.42){ const v = seg(u, 0.86, 1.42), r2 = rng(S.seed + 8); for(let i = 0; i < (S.calm ? 5 : 10); i++){ const a = r2() * Math.PI * 2, d = W * (0.45 + E.cubicOut(v) * 0.65), rr = W * 0.11 * (1 - v) * (0.6 + r2() * 0.8);\n      const x = cx + Math.cos(a) * d, y = -H * 0.6 + Math.sin(a) * d * 0.55 - v * 10; g.globalAlpha = 1 - v * 0.6; g.beginPath(); g.arc(x, y + 1.5, rr, 0, Math.PI * 2); g.fillStyle = C.dark; g.fill(); g.beginPath(); g.arc(x, y, rr * 0.9, 0, Math.PI * 2); g.fillStyle = C.mid; g.fill(); g.beginPath(); g.arc(x - rr * 0.25, y - rr * 0.3, rr * 0.45, 0, Math.PI * 2); g.fillStyle = C.light; g.fill(); g.globalAlpha = 1; } }\n  // 🥁 don! — the drum ring on the anvil (1.0) + a smaller echo\n  [[1.0, 1], [1.12, 0.6]].forEach(([at, k]) => { const v = seg(u, at, at + 0.32); if(v <= 0 || v >= 1) return; g.save(); g.globalAlpha = (1 - v) * k; g.strokeStyle = C.drum; g.lineWidth = 2.6 * k; const rr = W * (0.3 + v * 0.6) * k + W * 0.15;\n    g.beginPath(); g.ellipse(cx, -H * 0.42, rr, rr * 0.36, 0, 0, Math.PI * 2); if(day){ g.lineWidth = 4 * k; g.strokeStyle = 'rgba(80,60,0,0.45)'; g.stroke(); g.lineWidth = 2.6 * k; g.strokeStyle = C.drum; } g.stroke(); g.restore(); });\n}},\n// 🖤 bud — Lotus Bloom (Lotus Dew, I3) · ✨ mo-26 look test (polished): a pool + pads open (tell) → inner then outer petals close into a bud (snap + squash)\n//   → light leaks through the seams + 2 heartbeats → the bud sinks into the pool (onSwap 750, under water) → rises with mud running off →\n//   outer then inner petals spring open past open (overshoot) → ⚪ the new silhouette → pollen ring → petals wilt flat + break into chips · mud splats settle\nbud: {draw(g, S, u){\n  const H = S.H, W = S.W, cx = S.cx, TILT = 0.3, day = S.day, calm = S.calm;\n  const Rb = Math.max(W * 0.36, H * 0.3), budH = Math.max(H * 1.12, Rb * 2.2), L = Math.hypot(Rb, budH) * 1.02, phiC = -Math.atan2(Rb, budH) * 0.98, phiO = 1.22, TW = 0.62;\n  const COL = Object.assign({rim: day ? '#9C2F62' : '#B83A74', main: day ? '#E9679C' : '#FF7FB4', light: day ? '#F7B9D3' : '#FFC6DE', core: '#FFF4F8', back: day ? '#C24C80' : '#E0609A', inner: day ? '#F3A6C6' : '#FFB3D2',\n    pool: day ? '#3E8C8A' : '#1F6E78', poolL: day ? '#6FC0B8' : '#3FA3A6', pad: day ? '#4E9A3A' : '#5DB43C', padD: day ? '#2E6A22' : '#3A7A2A', mud: day ? '#5E3E22' : '#7A5434', gold: '#FFE38A'}, S.o.cols || {});\n  // ⏱️ per-petal open amount: 1 = open (lying out) · 0 = shut · > 1 = past open (overshoot / wilt)\n  const grow = E.backOut(seg(u, 0.04, 0.3)), wilt = seg(u, 1.2, T.end);\n  const openOf = (ring, i, n) => { const st = (i / n) * 0.03;\n    if(u < T.tell) return 1;\n    if(u < 0.62){ const a = ring ? 0.42 : T.tell; return 1 - E.cubicIn(seg(u, a + st, 0.6 + st * 0.3)); }\n    if(u < 0.95) return 0;\n    const a = ring ? 0.95 : 0.99; const v = seg(u, a + st, a + st + 0.15); const o = v < 1 ? E.backOut(v) : 1; return o + wilt * 0.55; };\n  // 🫧 the bud sinks into the pool (cubicIn) and rises with an overshoot (backOut)\n  let dy = 0; if(u >= 0.6 && u < T.swap) dy = H * 0.5 * E.cubicIn(seg(u, 0.62, T.swap)); else if(u >= T.swap && u < 0.95) dy = H * 0.5 * (1 - E.backOut(seg(u, T.swap, 0.93)));\n  const shutSq = Math.sin(Math.PI * seg(u, 0.6, 0.66)) * 0.07, budSx = 1 + shutSq, budSy = 1 - shutSq;\n  // pool + pads (tell → settle)\n  const poolA = E.cubicOut(seg(u, 0.0, 0.22)) * (1 - E.cubicIn(seg(u, 1.28, T.end))), prx = Rb * 1.75 * poolA, pry = prx * TILT;\n  if(poolA > 0){ g.save(); g.beginPath(); g.ellipse(cx, 1, prx, pry, 0, 0, Math.PI * 2); g.fillStyle = COL.pool; g.fill(); if(day){ g.lineWidth = 1.6; g.strokeStyle = 'rgba(20,40,40,0.5)'; g.stroke(); }\n    g.beginPath(); g.ellipse(cx - prx * 0.12, 1 - pry * 0.25, prx * 0.72, pry * 0.5, 0, Math.PI * 1.05, Math.PI * 1.75); g.lineWidth = 2; g.strokeStyle = COL.poolL; g.stroke(); g.restore();\n    [[-1, 0.9, 0.3], [1, 0.95, 0.75]].forEach(([sd, d, nt]) => { const px = cx + sd * prx * d * 0.92, py = 1 + pry * (sd > 0 ? 0.35 : -0.1), pr = Rb * 0.42 * poolA; g.save(); g.translate(px, py); g.scale(1, TILT * 1.15);\n      g.beginPath(); g.moveTo(0, 0); g.arc(0, 0, pr, nt * Math.PI * 2 + 0.35, nt * Math.PI * 2 + Math.PI * 2 - 0.05); g.closePath(); g.fillStyle = COL.padD; g.fill(); g.beginPath(); g.arc(0, -pr * 0.1, pr * 0.9, nt * Math.PI * 2 + 0.4, nt * Math.PI * 2 + Math.PI * 2 - 0.1); g.lineTo(0, -pr * 0.1); g.closePath(); g.fillStyle = COL.pad; g.fill(); g.restore(); }); }\n  // ripple rings on the pool: when the bud lands in it (0.62), dives (0.72) and comes up (0.8)\n  const ripple = (at, big) => { const v = seg(u, at, at + 0.4); if(v <= 0 || v >= 1 || poolA <= 0) return; g.save(); g.globalAlpha = (1 - v) * 0.9; g.strokeStyle = day ? '#2A6A6A' : '#BFF4FF'; g.lineWidth = 1.6;\n    g.beginPath(); g.ellipse(cx, 0, Rb * (0.7 + v * big), Rb * (0.7 + v * big) * TILT, 0, 0, Math.PI * 2); g.stroke(); g.restore(); };\n  ripple(0.62, 0.9); ripple(0.72, 1.1); ripple(0.8, 1.0); ripple(0.9, 0.8);\n  // 🌸 the petals (3D ring, projected with a 0.3 floor tilt, painted back → front)\n  const petals = [];\n  [[0, 5, Rb * 0.58, L * 0.86, Rb * 0.5, 0.31], [1, 7, Rb, L, Rb * 0.66, 0]].forEach(([ring, n, rr, len, wd, off]) => { for(let i = 0; i < n; i++){\n    const an = (i + 0.5 + off * n) / n * Math.PI * 2, o = openOf(ring, i, n), phi = lerp(phiC * (ring ? 1 : 0.92), phiO, o) + (o > 1 ? (o - 1) * 0.6 : 0);\n    const c = Math.cos(an), s = Math.sin(an), bz = s * rr, sc = grow * (1 - wilt * 0.35) * lerp(1, 0.6, cl(o, 0, 1.4) / 1.4 * 1.25);\n    const B = [cx + c * rr * budSx, -bz * TILT * -1 + dy], dx = c * Math.sin(phi), dyy = -Math.cos(phi), dz = s * Math.sin(phi);\n    const P = [B[0] + dx * len * sc * budSx, B[1] + (dyy * len * sc + dz * len * sc * TILT) * budSy], side = [-s * wd * sc, c * wd * sc * TW];\n    petals.push({ring, an, B, P, side, depth: bz + dz * len * 0.5, front: s > 0, o, i}); } });\n  petals.sort((a, b) => a.depth - b.depth);\n  const drawPetal = p => { const {B, P, side} = p, D = [P[0] - B[0], P[1] - B[1]], seam = p.o < 0.08;\n    const pt = (sx, f) => [B[0] + side[0] * sx + D[0] * f, B[1] + side[1] * sx + D[1] * f];\n    const shape = (k) => { const a1 = pt(1.0 * k, 0.32), a2 = pt(0.62 * k, 0.86), b1 = pt(-1.0 * k, 0.32), b2 = pt(-0.62 * k, 0.86); g.beginPath(); g.moveTo(B[0], B[1]); g.bezierCurveTo(a1[0], a1[1], a2[0], a2[1], P[0], P[1]); g.bezierCurveTo(b2[0], b2[1], b1[0], b1[1], B[0], B[1]); };\n    g.save(); g.globalAlpha = 1 - wilt * 0.85;\n    shape(1); g.fillStyle = COL.rim; g.fill(); if(day){ g.lineWidth = 1.5; g.strokeStyle = 'rgba(70,10,40,0.55)'; g.stroke(); }\n    shape(0.84); g.fillStyle = p.front ? COL.main : COL.back; g.fill();\n    // light band + white core (F4 cel bands), from the base half way up\n    g.save(); shape(0.84); g.clip(); g.beginPath(); const c1 = pt(0.5, 0.05), c2 = pt(0.42, 0.55), c3 = pt(-0.42, 0.55), c4 = pt(-0.5, 0.05), tipL = pt(0, 0.72);\n    g.moveTo(c1[0], c1[1]); g.quadraticCurveTo(c2[0], c2[1], tipL[0], tipL[1]); g.quadraticCurveTo(c3[0], c3[1], c4[0], c4[1]); g.closePath(); g.fillStyle = p.front ? COL.light : COL.inner; g.fill();\n    const d1 = pt(0.18, 0.12), d2 = pt(0, 0.5), d3 = pt(-0.18, 0.12); g.beginPath(); g.moveTo(d1[0], d1[1]); g.lineTo(d2[0], d2[1]); g.lineTo(d3[0], d3[1]); g.closePath(); g.fillStyle = COL.core; g.globalAlpha *= 0.85; g.fill(); g.restore();\n    // the midrib\n    const m0 = pt(0, 0.1), m1 = pt(0, 0.82); g.beginPath(); g.moveTo(m0[0], m0[1]); g.lineTo(m1[0], m1[1]); g.lineWidth = 1; g.strokeStyle = COL.rim; g.globalAlpha *= 0.5; g.stroke();\n    g.restore();\n    // 💡 light leaks through the seams while the bud is shut (front petals' edges)\n    if(seam && p.front && p.ring && Math.abs(Math.cos(p.an)) < 0.75 && u > 0.6 && u < 0.97){ const a = seg(u, 0.6, 0.66) * (1 - seg(u, 0.93, 0.97)) * (0.65 + 0.35 * beat); g.save(); g.globalAlpha = a; g.globalCompositeOperation = day ? 'source-over' : 'lighter';\n      const e1 = pt(0.66, 0.3), e2 = pt(0.42, 0.78); g.beginPath(); g.moveTo(B[0] + side[0] * 0.6, B[1] + side[1] * 0.6); g.quadraticCurveTo(e1[0], e1[1], e2[0], e2[1]); g.lineWidth = 1.3; g.globalAlpha *= 0.8; g.strokeStyle = day ? '#FFF0C0' : '#FFD86A'; g.lineCap = 'round'; g.stroke(); g.restore(); } };\n  // 💓 heartbeat inside the shut bud (2 beats, ≤ 3 a second, no flash)\n  const hb = (at) => { const v = seg(u, at, at + 0.09); return v > 0 && v < 1 ? Math.sin(Math.PI * v) : 0; }, beat = Math.max(hb(0.64), hb(0.8));\n  const clipPool = g2 => { g2.beginPath(); g2.rect(S.bx - 200, S.by - 300, S.bw + 400, -S.by + 300 + 0.5); g2.clip(); };\n  g.save(); clipPool(g); petals.filter(p => !p.front).forEach(drawPetal); g.restore();\n  // the body: old until shut · new from the opening (a small stretch as it rises)\n  if(u < 0.6) S.body(g, 'from', u);\n  else if(u >= 0.99){ const v = seg(u, 0.99, 1.2), st = Math.sin(Math.PI * v) * 0.06; S.body(g, 'to', u, {sx: 1 - st * 0.5, sy: 1 + st}); if(pop(g, S, u, 1.02, {sx: 1 - st * 0.5, sy: 1 + st})){} }\n  // inner glow of the shut bud\n  if(u > 0.58 && u < 0.98){ const a = seg(u, 0.58, 0.64) * (1 - seg(u, 0.94, 0.98)); dot(g, S, cx, -budH * 0.45 + dy, budH * (0.5 + beat * 0.12), 'rgba(255,170,210,0.75)', a * (0.45 + beat * 0.3) * (calm ? 0.6 : 1)); }\n  g.save(); clipPool(g); petals.filter(p => p.front).forEach(drawPetal); g.restore();\n  // 🟤 mud runs off the rising bud and drips from the petal tips → splats + tiny rings on the pool (slow, heavy bits)\n  const r = rng(S.seed + 6), nD = calm ? 4 : 7;\n  for(let i = 0; i < nD; i++){ const x = cx + (r() - 0.5) * Rb * 1.7, y0 = -budH * (0.35 + r() * 0.45), t0 = 0.8 + i * 0.035, v = seg(u, t0, t0 + 0.42 + r() * 0.1);\n    if(v <= 0) continue; const land = v >= 1, y = land ? 0 : lerp(y0 + dy, 0, E.cubicIn(v)), xs = x + (land ? 0 : Math.sin(v * 3 + i) * 1.5);\n    if(!land){ g.fillStyle = COL.mud; g.beginPath(); g.moveTo(xs, y - 4.5); g.quadraticCurveTo(xs + 2.6, y + 0.5, xs, y + 2.6); g.quadraticCurveTo(xs - 2.6, y + 0.5, xs, y - 4.5); g.fill(); if(day){ g.lineWidth = 0.8; g.strokeStyle = 'rgba(30,15,5,0.6)'; g.stroke(); } }\n    else { const w = seg(u, t0 + 0.52, T.end + 0.1), sp = 1 - w; if(sp <= 0) continue; g.save(); g.globalAlpha = sp; g.fillStyle = COL.mud; g.beginPath(); g.ellipse(x, 0, 3.4, 1.2, 0, 0, Math.PI * 2); g.fill();\n      g.strokeStyle = day ? '#2A6A6A' : '#BFF4FF'; g.lineWidth = 1; g.beginPath(); g.ellipse(x, 0, 3 + (1 - sp) * 9, (3 + (1 - sp) * 9) * TILT, 0, 0, Math.PI * 2); g.stroke(); g.restore(); } }\n  // 🌼 pollen ring burst at the opening + pollen drifting up after (F5: dots break up and shrink)\n  if(u > 1.02){ const v = seg(u, 1.02, 1.32); if(v < 1){ g.save(); g.globalAlpha = (1 - v) * 0.9; g.strokeStyle = day ? '#C89000' : COL.gold; g.lineWidth = 2.6 * (1 - v) + 0.6;\n      g.beginPath(); g.ellipse(cx, -H * 0.45, Rb * (0.6 + v * 1.5), Rb * (0.6 + v * 1.5) * 0.55, 0, 0, Math.PI * 2); g.stroke(); g.restore(); }\n    const r2 = rng(S.seed + 11), nP = calm ? 7 : 14; for(let i = 0; i < nP; i++){ const an = r2() * Math.PI * 2, sp = 0.6 + r2() * 0.6, w = seg(u, 1.02, 1.5), d = Rb * (0.3 + E.cubicOut(w) * 1.5 * sp);\n      const x = cx + Math.cos(an) * d, y = -H * 0.45 + Math.sin(an) * d * 0.55 - w * 18 * sp; if(w < 1) sparkle(g, S, x, y, (2.6 + r2() * 1.4) * (1 - w), COL.gold, 1 - w * 0.9); } }\n  // 🍂 wilting petals break into chips that flutter down onto the pool\n  if(wilt > 0){ const r3 = rng(S.seed + 13); for(let i = 0; i < (calm ? 5 : 10); i++){ const p = petals[i % petals.length], f = 0.4 + r3() * 0.5, x = lerp(p.B[0], p.P[0], f) + Math.sin(u * 8 + i) * 4 * wilt, y = lerp(p.B[1], p.P[1], f) + wilt * 14 * (0.5 + r3());\n      g.save(); g.translate(x, Math.min(0, y)); g.rotate(Math.sin(u * 6 + i) * 0.8); g.globalAlpha = 1 - wilt; g.fillStyle = i % 2 ? COL.main : COL.light; g.beginPath(); g.ellipse(0, 0, 3.6 * (1 - wilt * 0.5), 1.8, 0, 0, Math.PI * 2); g.fill(); g.restore(); } }\n}},\n// 🟥 swirl — Sand Swirl-Up (Haboob, I3): he sinks into the sand, the hats fly UP, he rises in the new form and the hats rain down onto it\nswirl: {draw(g, S, u){\n  const H = S.H, W = S.W, cx = S.cx, day = S.day, sand = day ? '#C99A52' : '#E8B86A', dk = day ? '#8A6230' : '#B07D3E';\n  const sink = E.cubicIn(seg(u, 0.38, 0.72)), rise = u >= T.swap ? 1 - E.backOut(seg(u, T.swap, 1.1)) : 1;\n  const clipG = g2 => { g2.beginPath(); g2.rect(S.bx - 80, S.by - 300, S.bw + 160, -S.by + 300); g2.clip(); };\n  // ripple rings in the sand\n  const rings = (n, a) => { g.save(); g.strokeStyle = dk; g.lineWidth = 2; for(let i = 0; i < n; i++){ const v = (u * 1.6 + i / n) % 1; g.globalAlpha = a * (1 - v); g.beginPath(); g.ellipse(cx, 0, W * (0.3 + v * 0.7), W * (0.06 + v * 0.12), 0, 0, Math.PI * 2); g.stroke(); } g.restore(); };\n  if(u > 0.05 && u < 1.3) rings(3, seg(u, 0.05, 0.3) * (1 - seg(u, 1.1, 1.3)));\n  // the sand swirl (a rising spiral of grains)\n  const sw = seg(u, 0.35, 0.5) * (1 - seg(u, 1.0, 1.25));\n  const grains = back => { if(sw <= 0) return; for(let i = 0; i < 26; i++){ const v = (i / 26 + u * 0.9) % 1, an = v * Math.PI * 6 + i, s = Math.sin(an); if(back !== (s < 0)) continue;\n      const gx = cx + Math.cos(an) * W * (0.35 + v * 0.45), gy = -v * H * 1.1 + s * 6; g.fillStyle = i % 3 ? sand : dk; g.globalAlpha = sw * (1 - v * 0.6); g.fillRect(gx - 1.6, gy - 1.6, 3.2, 3.2); } g.globalAlpha = 1; };\n  grains(true);\n  g.save(); clipG(g);\n  if(u < T.swap){ const sq = Math.sin(Math.PI * seg(u, 0.35, 0.45)) * 0.1; S.body(g, 'from', u, {dy: H * 1.1 * sink, sx: 1 + sq, sy: 1 - sq}); }\n  else { const st = u < 1.1 ? 0.1 * (1 - seg(u, T.swap, 1.1)) : -Math.sin(Math.PI * seg(u, 1.1, 1.22)) * 0.08; S.body(g, 'to', u, {dy: H * 1.1 * rise, sx: 1 - st, sy: 1 + st}); }\n  g.restore();\n  // the sand mound lip at the hole\n  if(u > 0.36 && u < 1.15){ const a = seg(u, 0.36, 0.45) * (1 - seg(u, 1.05, 1.15)); g.save(); g.globalAlpha = a; g.fillStyle = sand; g.beginPath(); g.ellipse(cx, 0, W * 0.62, W * 0.12, 0, 0, Math.PI); g.fill(); g.fillStyle = dk; g.beginPath(); g.ellipse(cx, 1, W * 0.5, W * 0.07, 0, 0, Math.PI * 2); g.fill(); g.restore(); }\n  grains(false);\n  // 🎩 the hats: up at the sink, rain down onto the new form (Motion.hang-style spring on landing)\n  const hats = S.o.bits || [0, 1, 2], topA = S.A.y0, topB = S.B.y0;\n  hats.forEach((bit, i) => { const up = E.cubicOut(seg(u, 0.38 + i * 0.03, 0.85)), dn = E.cubicIn(seg(u, 0.88 + i * 0.05, 1.22 + i * 0.05)), land = seg(u, 1.22 + i * 0.05, 1.42 + i * 0.05);\n    const yStart = topA - i * 9, yTop = topA - H * (0.34 + i * 0.1), yEnd = topB - i * 9, y = u < 0.88 + i * 0.05 ? lerp(yStart, yTop, up) : lerp(yTop, yEnd, dn), x = cx + (i - 1) * 6 * Math.sin(u * 7) * (1 - land), spin = (u < 1.22 + i * 0.05) ? Math.sin(u * 11 + i) * 0.6 : Math.sin(land * 9) * 0.25 * (1 - land);\n    const sq = land > 0 ? Math.sin(Math.PI * land) * 0.25 * (1 - land) : 0;\n    g.save(); g.translate(x, y); g.rotate(spin); g.scale(1 + sq, 1 - sq);\n    if(typeof bit === 'function') bit(g, {i, u}); else { g.fillStyle = ['#D8452E', '#E0662E', '#C23A5A'][i % 3]; g.beginPath(); g.moveTo(-8, 0); g.lineTo(-6, -11); g.lineTo(6, -11); g.lineTo(8, 0); g.closePath(); g.fill(); g.fillStyle = '#FFE58A'; g.fillRect(-8, -2.5, 16, 2.5); g.strokeStyle = '#3a1a10'; g.lineWidth = 1; if(S.day) g.stroke(); g.fillStyle = '#2A2A2A'; g.fillRect(-0.8, -15, 1.6, 4); }\n    g.restore(); });\n  // 💨 sand puffs burst out as he comes up (lumpy cel puffs that erode, F5 — no ⚪ for sand)\n  if(u > 0.8 && u < 1.3){ const v = seg(u, 0.8, 1.3), r = rng(S.seed + 3); for(let i = 0; i < (S.calm ? 5 : 9); i++){ const an = Math.PI + (i + 0.5) / 9 * Math.PI, d = W * (0.35 + E.cubicOut(v) * 0.6), rr = W * 0.13 * (1 - v) * (0.7 + r() * 0.6), x = cx + Math.cos(an) * d, y = Math.sin(an) * d * 0.35 - v * 10;\n    g.globalAlpha = 1 - v * 0.5; g.fillStyle = dk; g.beginPath(); g.arc(x, y + 1.5, rr, 0, Math.PI * 2); g.fill(); g.fillStyle = sand; g.beginPath(); g.arc(x, y, rr * 0.9, 0, Math.PI * 2); g.fill(); g.fillStyle = day ? '#F2D9A8' : '#FFE6B8'; g.beginPath(); g.arc(x - rr * 0.25, y - rr * 0.3, rr * 0.4, 0, Math.PI * 2); g.fill(); } g.globalAlpha = 1; }\n}},\n// 🦁 pageFlip — Tablet Flip (Sphinx, I3): she flips like a page (the stone-tablet back shows between), a sand gust whirls, the light of the hour washes over her\npageFlip: {draw(g, S, u){\n  const H = S.H, W = S.W, cx = S.cx, hx = S.cx - S.W * 0.55, hour = S.o.hour || 'noon', HC = {noon: ['#FFD54A', 'rgba(255,214,90,0.9)'], dusk: ['#FF8A3A', 'rgba(255,140,60,0.9)'], night: ['#5A7CFF', 'rgba(110,140,255,0.9)']}[hour] || ['#FFD54A', 'rgba(255,214,90,0.9)'];\n  const ph = seg(u, T.tell, 1.1), ang = E.sine(ph) * Math.PI * 2, cs = Math.cos(ang), face = cs >= 0, sxv = Math.max(0.04, Math.abs(cs));\n  const showing = ang < Math.PI / 2 ? 'from' : ang < Math.PI * 1.5 ? 'back' : 'to';\n  // sand gust ring behind\n  const gust = back => { const a = seg(u, 0.45, 0.6) * (1 - seg(u, 1.05, 1.25)); if(a <= 0) return; g.save(); g.strokeStyle = S.day ? '#A87A3A' : '#F0C880'; g.lineCap = 'round'; g.lineWidth = 2;\n    for(let i = 0; i < 4; i++){ const a0 = u * 8 + i * 1.6, yy = -H * (0.2 + i * 0.22); for(let s = 0; s < 2; s++){ const st = a0 + s * Math.PI; const inBack = Math.sin(st + 0.8) < 0; if(back !== inBack) continue; g.globalAlpha = a; g.beginPath(); g.ellipse(cx, yy, W * 0.8, W * 0.16, 0, st, st + 1.2); rimStroke(g, S, 2); g.stroke(); } } g.restore(); };\n  gust(true);\n  g.save(); g.translate(hx, 0); g.transform(sxv, (face ? 1 : -1) * Math.sin(ang) * 0.04, 0, 1, 0, 0); g.translate(-hx, 0);\n  const shade = [S.by, S.by + S.bh, S.day ? '#3A2A10' : '#120A28', (1 - sxv) * 0.45];\n  if(showing === 'from') S.body(g, 'from', u, {tint: [shade]}); else if(showing === 'to'){ const wash = seg(u, 1.0, 1.4), y0 = lerp(-H * 1.1, 0, wash); S.body(g, 'to', u, {tint: [shade].concat(wash > 0 && wash < 1 ? [[y0 - H * 0.35, y0, HC[0], 0.55], [y0 - H * 0.6, y0 - H * 0.35, HC[0], 0.25]] : [])}); }\n  else { // the tablet back: our own stone page with 3 rows of simple marks\n    const tw = W * 1.05, th = H * 1.05, x0 = cx - tw / 2, y0 = -th; g.fillStyle = S.day ? '#C9A66A' : '#E2C48A'; g.strokeStyle = S.day ? '#6a4a20' : '#8A6A3A'; g.lineWidth = 3;\n    g.beginPath(); g.moveTo(x0 + 10, y0); g.lineTo(x0 + tw - 10, y0); g.quadraticCurveTo(x0 + tw, y0, x0 + tw, y0 + 10); g.lineTo(x0 + tw, 0); g.lineTo(x0, 0); g.lineTo(x0, y0 + 10); g.quadraticCurveTo(x0, y0, x0 + 10, y0); g.fill(); g.stroke();\n    g.fillStyle = S.day ? '#7a5a2a' : '#9A7440'; for(let r = 0; r < 4; r++) for(let c = 0; c < 4; c++){ const mx = x0 + tw * (0.18 + c * 0.21), my = y0 + th * (0.18 + r * 0.2); if((r + c) % 3 === 0){ g.beginPath(); g.arc(mx, my, 4, 0, Math.PI * 2); g.fill(); } else if((r + c) % 3 === 1) g.fillRect(mx - 5, my - 1.5, 10, 3); else { g.beginPath(); g.moveTo(mx, my - 5); g.lineTo(mx + 5, my + 4); g.lineTo(mx - 5, my + 4); g.closePath(); g.fill(); } } }\n  g.restore();\n  // the page edge glint when edge-on\n  if(sxv < 0.25 && u > T.tell && u < 1.1){ const a = 1 - sxv / 0.25; g.save(); g.globalAlpha = a; g.strokeStyle = S.day ? '#6a4a20' : '#FFF1C8'; g.lineWidth = 2.6; g.beginPath(); g.moveTo(hx + 2, -H * 1.05); g.lineTo(hx + 2, 0); g.stroke(); g.restore(); dot(g, S, hx, -H * 0.5, H * 0.3, 'rgba(255,230,160,0.7)', a * 0.5); }\n  if(showing === 'to') pop(g, S, u, 1.1);\n  gust(false);\n  // the hour light: soft glow + 4 sparkles in the hour colour\n  if(u > 1.0){ const v = seg(u, 1.0, T.end); dot(g, S, cx, -H * 0.6, H * 0.7, HC[1], 0.45 * (1 - v)); const r = rng(S.seed + 5); for(let i = 0; i < 5; i++) sparkle(g, S, cx + (r() - 0.5) * W * 1.6, -H * (0.2 + r()) - v * 10, 2.6 * (1 - v), HC[0], 1 - v); }\n}},\n// 🔆 lampTurn — Lamp Turn (Beacon, I3): the lamp spins a full circle, its beam sweeps; where it has passed = the new form, one storey taller\nlampTurn: {draw(g, S, u){\n  const H = S.H, W = S.W, cx = S.cx, lamp = S.o.lamp || [S.A.hx, S.A.y0 + H * 0.1], beamL = H * 2.2, sweep = E.sine(seg(u, T.tell, T.reveal)), a0 = Math.PI, an = a0 + sweep * Math.PI * 2;\n  const y0 = S.B.y0, storey = u >= T.swap ? H * 0.14 * (1 - E.backOut(seg(u, T.swap, 1.2))) : 0;\n  const sector = (g2, from, to) => { g2.beginPath(); g2.moveTo(lamp[0], lamp[1]); g2.arc(lamp[0], lamp[1], 900, from, to); g2.closePath(); g2.clip(); };\n  // tell: the lamp warms up + 4 clockwork ticks\n  const warm = seg(u, 0.02, 0.3);\n  if(u < T.tell){ g.save(); g.strokeStyle = S.day ? '#8A5A00' : '#FFE58A'; g.lineWidth = 2; g.lineCap = 'round'; for(let i = 0; i < 4; i++){ const a = i * Math.PI / 2 + Math.floor(u * 20) * 0.2; g.globalAlpha = warm; g.beginPath(); g.moveTo(lamp[0] + Math.cos(a) * 12, lamp[1] + Math.sin(a) * 12); g.lineTo(lamp[0] + Math.cos(a) * 18, lamp[1] + Math.sin(a) * 18); g.stroke(); } g.restore(); }\n  // beam behind the bodies (the far half)\n  const beam = () => { if(u < T.tell || u > T.reveal + 0.08) return; const fade = 1 - seg(u, T.reveal, T.reveal + 0.08); g.save(); g.globalAlpha = 0.55 * fade; g.globalCompositeOperation = S.day ? 'source-over' : 'lighter';\n    g.fillStyle = S.day ? 'rgba(255,200,60,0.55)' : 'rgba(255,230,140,0.75)'; g.beginPath(); g.moveTo(lamp[0], lamp[1]); g.arc(lamp[0], lamp[1], beamL, an - 0.16, an + 0.16); g.closePath(); g.fill();\n    g.fillStyle = S.day ? 'rgba(255,240,180,0.6)' : 'rgba(255,250,220,0.9)'; g.beginPath(); g.moveTo(lamp[0], lamp[1]); g.arc(lamp[0], lamp[1], beamL, an - 0.05, an + 0.05); g.closePath(); g.fill(); g.restore(); };\n  beam();\n  if(u < T.tell) S.body(g, 'from', u); else if(u < T.reveal){ S.body(g, 'from', u, {clip: g2 => sector(g2, an, a0 + Math.PI * 2)}); S.body(g, 'to', u, {clip: g2 => sector(g2, a0, an), dy: storey}); }\n  else S.body(g, 'to', u, {dy: storey});\n  // the lit shadow edge on the body (a thin gold line along the beam)\n  if(u > T.tell && u < T.reveal){ g.save(); g.strokeStyle = S.day ? '#C88A00' : '#FFF4B0'; g.lineWidth = 2; g.globalAlpha = 0.9; g.beginPath(); g.moveTo(lamp[0], lamp[1]); g.lineTo(lamp[0] + Math.cos(an) * H * 1.2, lamp[1] + Math.sin(an) * H * 1.2); rimStroke(g, S, 2); g.stroke(); g.restore(); }\n  // the lamp itself\n  const lampP = u >= T.swap ? [lamp[0], lamp[1] - (S.A.y0 - S.B.y0) * seg(u, T.swap, 1.2)] : lamp;\n  dot(g, S, lampP[0], lampP[1], 14 + warm * 10, 'rgba(255,230,120,0.95)', 0.6 + warm * 0.4);\n  if(u >= T.reveal) pop(g, S, u, T.reveal);\n  // CLICK: 2 gold rings from the lamp at the end\n  if(u > T.reveal){ const v = seg(u, T.reveal, T.end); for(let i = 0; i < 2; i++){ const w = seg(v, i * 0.25, 0.75 + i * 0.25); if(w <= 0 || w >= 1) continue; g.save(); g.globalAlpha = 1 - w; g.strokeStyle = S.day ? '#B07A00' : '#FFE58A'; g.lineWidth = 2; g.beginPath(); g.arc(lampP[0], lampP[1], 8 + w * 34, 0, Math.PI * 2); rimStroke(g, S, 2); g.stroke(); g.restore(); }\n    const r = rng(S.seed + 4); for(let i = 0; i < 4; i++) sparkle(g, S, lampP[0] + (r() - 0.5) * 70, lampP[1] + (r() - 0.5) * 50, 2.6 * (1 - v), '#FFF4B0', 1 - v); }\n}},\n// 🔥 climb — Surt (I5): the magma climbs from the feet to the head; below the heat line = the new form, still glowing (hot → cool, F3); a crown flare at the top\nclimb: {shake: (S, u) => S.calm ? 0 : (u > 0.05 && u < T.tell ? 1.2 * Math.sin(Math.PI * seg(u, 0.05, T.tell)) : 0),\n draw(g, S, u){\n  const H = S.H, W = Math.min(S.W, (S.A.x1 - S.A.x0) * 1.1), cx = S.A.hx, topY = Math.min(S.A.y0, S.B.y0) - 4, line = lerp(6, topY, E.sine(seg(u, T.tell, 1.1))), done = u >= 1.1;\n  const hot = ['#FFFBE0', '#FFD84A', '#FF8A2A', '#D83A1E'];\n  // tell: ground cracks glow at the feet + embers\n  const cr = seg(u, 0.03, 0.3) * (1 - seg(u, 1.0, 1.3));\n  if(cr > 0){ const r = rng(S.seed + 2); g.save(); g.lineCap = 'round'; for(let i = 0; i < 6; i++){ const a = Math.PI + (i + 0.5) / 6 * Math.PI * -1 + (r() - 0.5) * 0.3, L = W * (0.5 + r() * 0.4) * cr;\n      g.beginPath(); g.moveTo(cx, 0); let px = cx, py = 0; for(let s = 1; s <= 3; s++){ px = cx + Math.cos(a) * L * s / 3 + (r() - 0.5) * 6; py = Math.sin(a) * L * 0.22 * s / 3 * -1; g.lineTo(px, py); }\n      g.lineWidth = 3.4; g.strokeStyle = S.day ? '#6a1a0a' : '#5a1a0a'; g.stroke(); g.lineWidth = 1.6; g.strokeStyle = '#FFB040'; g.stroke(); } g.restore(); dot(g, S, cx, 0, W * 0.8, 'rgba(255,120,40,0.6)', cr * 0.5); }\n  // bodies: old above the heat line, new below it with cel heat bands right under the line\n  const clipA = g2 => { g2.beginPath(); g2.rect(S.bx - 80, S.by - 80, S.bw + 160, line - S.by + 80); g2.clip(); }, clipB = g2 => { g2.beginPath(); g2.rect(S.bx - 80, line, S.bw + 160, 400); g2.clip(); };\n  const cool = seg(u, 1.1, T.end), bands = [[line, line + H * 0.07, hot[0], 0.85 * (1 - cool)], [line + H * 0.07, line + H * 0.18, hot[1], 0.6 * (1 - cool)], [line + H * 0.18, line + H * 0.34, hot[2], 0.4 * (1 - cool)], [line + H * 0.34, line + H * 0.55, hot[3], 0.22 * (1 - cool)]];\n  if(!done){ S.body(g, 'from', u, {clip: clipA, tint: [[line - H * 0.08, line, hot[2], 0.35]]}); if(u > T.tell) S.body(g, 'to', u, {clip: clipB, tint: bands}); }\n  else S.body(g, 'to', u, {tint: bands});\n  // the heat line: glow beads + embers rising off it\n  if(u > T.tell && !done){ dot(g, S, cx, line, W * 0.45, 'rgba(255,150,50,0.8)', 0.45);\n    const r = rng(S.seed + 7); for(let i = 0; i < 10; i++){ const v = (u * 2.2 + r()) % 1, x = cx + (r() - 0.5) * W * 1.0 + Math.sin(u * 9 + i) * 3, y = line - v * H * 0.35; g.fillStyle = v < 0.4 ? hot[1] : hot[2]; g.globalAlpha = 1 - v; g.fillRect(x - 1.5, y - 1.5, 3, 3); } g.globalAlpha = 1; }\n  // the crown flare at the top: 7 flame tongues + ⚪ + sparks (horns · veins · mantle flare)\n  if(u >= 1.1){ const v = seg(u, 1.1, T.end), r = rng(S.seed + 1), hy = S.B.y0 + 2; pop(g, S, u, 1.1);\n    for(let i = 0; i < 7; i++){ const an = -Math.PI / 2 + (i - 3) * 0.32, len = H * 0.3 * Math.sin(Math.PI * Math.min(1, v * 1.6)) * (0.7 + r() * 0.5); if(len <= 0) continue;\n      const bx = S.B.hx + Math.cos(an) * 10, by = hy + 6; g.save(); g.translate(bx, by); g.rotate(an + Math.PI / 2); for(let b = 0; b < 3; b++){ const s = 1 - b * 0.3; g.beginPath(); g.moveTo(-5 * s, 0); g.quadraticCurveTo(-4 * s, -len * 0.6 * s, 0, -len * s); g.quadraticCurveTo(4 * s, -len * 0.6 * s, 5 * s, 0); g.closePath(); g.fillStyle = [hot[3], hot[2], hot[1]][b]; g.fill(); } g.restore(); }\n    for(let i = 0; i < 8; i++){ const an = r() * Math.PI * 2, d = 10 + v * 40 * (0.6 + r()); sparkle(g, S, S.B.hx + Math.cos(an) * d, hy + Math.sin(an) * d * 0.7 - v * 10, 2.4 * (1 - v), hot[1], 1 - v); } }\n}}\n};\n// 🔊 per-kind moments for S.on (UISound names them; times in s on the 1.5 s clock)\nconst EVENTS = {wipe: [['chime', 0.35]], ringLift: [['gust', 0.06], ['drop', 1.2]], fanSnap: [['snap', 0.38], ['tak', 0.86]], swell: [['rumble', 0.45], ['don', 1.0]],\n  bud: [['shut', 0.6], ['dive', 0.62], ['bloom', 1.02]], swirl: [['sink', 0.38], ['emerge', 0.8], ['hats', 1.22]], pageFlip: [['flip', 0.6], ['flip2', 1.0]], lampTurn: [['tick', 0.05], ['click', 1.15]], climb: [['rumble', 0.05], ['flare', 1.1]]};\nM.swap = swap; M.SWAP = {KINDS: Object.keys(KINDS), T, EVENTS, VERSION: 'mo-26'};\nif (M.needDef) M.needDef('swap', {has: () => !!M.SWAP});\nM.FX_STYLES = Object.assign({}, M.FX_STYLES || {}, {swap: Object.keys(KINDS)});\n})();\n</script>\n<!-- (mo-26) END OF MotionSwap.html -->\n");
